import re
from typing import List, Tuple

def compare_versions(a: str, b: str) -> int:
    version_pattern = re.compile(r'^(0|[1-9]\d*)(\.(0|[1-9]\d*)){2}(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$')

    if not version_pattern.match(a) or not version_pattern.match(b):
        raise ValueError("Invalid version string")

    main_a, pre_a = _split_version(a)
    main_b, pre_b = _split_version(b)

    comparison = _compare_main_versions(main_a, main_b)
    if comparison != 0:
        return comparison

    if pre_a is None and pre_b is not None:
        return 1  # a is greater because it has no pre-release
    if pre_a is not None and pre_b is None:
        return -1  # b is greater because it has no pre-release

    return _compare_pre_releases(pre_a, pre_b)

def _split_version(version: str) -> Tuple[Tuple[int, int, int], List[str]]:
    main, _, pre = version.partition('-')
    major, minor, patch = map(int, main.split('.'))
    pre_release = pre.split('.') if pre else None
    return (major, minor, patch), pre_release

def _compare_main_versions(main_a: Tuple[int, int, int], main_b: Tuple[int, int, int]) -> int:
    for a, b in zip(main_a, main_b):
        if a < b:
            return -1
        elif a > b:
            return 1
    return 0

def _compare_pre_releases(pre_a: List[str], pre_b: List[str]) -> int:
    for a, b in zip(pre_a, pre_b):
        if a.isdigit() and not b.isdigit():
            return -1  # numeric < alphanumeric
        if not a.isdigit() and b.isdigit():
            return 1  # alphanumeric > numeric
        if a < b:
            return -1
        elif a > b:
            return 1
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1
    return 0

import re
from typing import List

def compare_versions(a: str, b: str) -> int:
    def _validate_version(version: str) -> None:
        pattern = r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$'
        if not re.match(pattern, version):
            raise ValueError(f"Invalid version string: {version}")

    def _parse_version(version: str) -> List:
        main, _, prerelease = version.partition('-')
        major, minor, patch = map(int, main.split('.'))
        if prerelease:
            prerelease_parts = prerelease.split('.')
            # Validate pre-release parts
            for part in prerelease_parts:
                if part.isdigit() and part.startswith('0') and part != '0':
                    raise ValueError(f"Invalid version string: {version}")
        else:
            prerelease_parts = []
        return [major, minor, patch, prerelease_parts]

    _validate_version(a)
    _validate_version(b)

    a_parts = _parse_version(a)
    b_parts = _parse_version(b)

    # Compare major, minor, and patch
    for i in range(3):
        if a_parts[i] < b_parts[i]:
            return -1
        elif a_parts[i] > b_parts[i]:
            return 1

    # Compare pre-release versions
    a_prerelease = a_parts[3]
    b_prerelease = b_parts[3]

    if a_prerelease and not b_prerelease:
        return -1
    if not a_prerelease and b_prerelease:
        return 1

    # If both have pre-releases, compare them
    for a_id, b_id in zip(a_prerelease, b_prerelease):
        if a_id.isdigit() and not b_id.isdigit():
            return -1
        if not a_id.isdigit() and b_id.isdigit():
            return 1
        if a_id < b_id:
            return -1
        elif a_id > b_id:
            return 1

    # If they are equal up to the length of the shorter list
    if len(a_prerelease) < len(b_prerelease):
        return -1
    if len(a_prerelease) > len(b_prerelease):
        return 1

    return 0

