from typing import List

def compare_versions(a: str, b: str) -> int:
    if not _is_valid_semantic_version(a) or not _is_valid_semantic_version(b):
        raise ValueError("Invalid version string")

    a_parts = _split_version(a)
    b_parts = _split_version(b)

    # Compare MAJOR, MINOR, PATCH
    for a_part, b_part in zip(a_parts[:3], b_parts[:3]):
        if a_part < b_part:
            return -1
        elif a_part > b_part:
            return 1

    # If MAJOR, MINOR, PATCH are equal, check pre-release
    if len(a_parts) > 3 and len(b_parts) <= 3:
        return -1  # a has pre-release, b does not
    if len(a_parts) <= 3 and len(b_parts) > 3:
        return 1   # b has pre-release, a does not

    # Compare pre-release identifiers if they exist
    if len(a_parts) > 3 and len(b_parts) > 3:
        return _compare_pre_release(a_parts[3:], b_parts[3:])

    # If both have no pre-release, they are equal
    return 0

def _split_version(version: str) -> List[str]:
    # Split version into major, minor, patch, pre-release, and build
    main_parts = version.split('+')[0].split('-')
    version_numbers = main_parts[0].split('.')
    pre_release = main_parts[1] if len(main_parts) > 1 else ''
    return version_numbers + (pre_release.split('.') if pre_release else [])

def _compare_pre_release(a_pre: List[str], b_pre: List[str]) -> int:
    for a_id, b_id in zip(a_pre, b_pre):
        if a_id.isdigit() and b_id.isdigit():
            # Compare numeric identifiers
            if int(a_id) < int(b_id):
                return -1
            elif int(a_id) > int(b_id):
                return 1
        elif a_id.isdigit():
            return -1  # Numeric < alphanumeric
        elif b_id.isdigit():
            return 1   # Alphanumeric > numeric
        else:
            # Compare alphanumeric identifiers
            if a_id < b_id:
                return -1
            elif a_id > b_id:
                return 1

    # If all shared identifiers are equal, the longer list wins
    return -1 if len(a_pre) < len(b_pre) else 1 if len(a_pre) > len(b_pre) else 0

def _is_valid_semantic_version(version: str) -> bool:
    pattern = r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?(\+([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$'
    match = re.match(pattern, version)
    if not match:
        return False

    # Check for leading zeros in version numbers
    version_numbers = version.split('+')[0].split('-')[0].split('.')
    for number in version_numbers:
        if len(number) > 1 and number[0] == '0':
            return False

    return True

