import pytest
from solution import compare_versions
from hypothesis import given, strategies as st


def test_example_equal_versions():
    assert compare_versions('1.0.0', '1.0.0') == 0, f"got {compare_versions('1.0.0', '1.0.0')!r}"

def test_example_a_less_than_b():
    assert compare_versions('1.0.0', '1.0.1') == -1, f"got {compare_versions('1.0.0', '1.0.1')!r}"

def test_example_a_greater_than_b():
    assert compare_versions('1.0.2', '1.0.1') == 1, f"got {compare_versions('1.0.2', '1.0.1')!r}"

def test_example_with_prerelease():
    assert compare_versions('1.0.0-alpha', '1.0.0') == -1, f"got {compare_versions('1.0.0-alpha', '1.0.0')!r}"

def test_example_prerelease_identifiers():
    assert compare_versions('1.0.0-alpha', '1.0.0-alpha.1') == -1, f"got {compare_versions('1.0.0-alpha', '1.0.0-alpha.1')!r}"

def test_example_numeric_vs_alphanumeric():
    assert compare_versions('1.0.0-alpha', '1.0.0-beta') == -1, f"got {compare_versions('1.0.0-alpha', '1.0.0-beta')!r}"

def test_example_invalid_version():
    with pytest.raises(ValueError):
        compare_versions('1.0.0.0', '1.0.0')

def test_example_invalid_leading_zero():
    with pytest.raises(ValueError):
        compare_versions('01.0.0', '1.0.0')

def test_example_empty_string():
    with pytest.raises(ValueError):
        compare_versions('', '1.0.0')

def test_property_version_ordering():
    @given(st.text(min_size=1, max_size=12))
    def check_ordering(version):
        assert compare_versions(version, version) == 0, f"got {compare_versions(version, version)!r}"


