def parse_csv_line(line: str) -> list[str]:
    if line == "":
        return ['']

    fields = []
    current_field = []
    in_quotes = False
    i = 0

    while i < len(line):
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check if the next character is also a quote for escaping
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the next quote
                else:
                    in_quotes = False  # End of quoted field
            else:
                current_field.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)

        i += 1

    # Handle the last field
    if in_quotes:
        raise ValueError("Unterminated quoted field")

    fields.append(''.join(current_field))

    # Check the last character to ensure it ends correctly
    if len(line) > 0 and line[-1] != ',':
        fields.append('')  # Trailing empty field if line ends without a comma

    return fields

