    in_quotes = False
    i = 0
    length = len(line)

    while i < length:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check if the next character is also a quote (escaped quote)
                if i + 1 < length and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the next quote
                else:
                    in_quotes = False  # End of quoted field
                    # Check if the next character is a comma or end of line
                    if i + 1 < length and line[i + 1] not in [',', '']:
                        raise ValueError("Invalid format after quoted field")
            else:
                current_field.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)

        i += 1

    if in_quotes:
        raise ValueError("Unterminated quoted field")

    fields.append(''.join(current_field))  # Add the last field

    return fields

