import pytest
from solution import evaluate
from hypothesis import given, strategies as st


def test_example_valid_expression():
    assert evaluate('3 + 5') == 8.0, f"got {evaluate('3 + 5')!r}"

def test_example_expression_with_parentheses():
    assert evaluate('(2 + 3) * 4') == 20.0, f"got {evaluate('(2 + 3) * 4')!r}"

def test_example_expression_with_unary_minus():
    assert evaluate('-3 + 5') == 2.0, f"got {evaluate('-3 + 5')!r}"

def test_example_expression_with_power():
    assert evaluate('2 ** 3') == 8.0, f"got {evaluate('2 ** 3')!r}"

def test_example_division_by_zero():
    with pytest.raises(ZeroDivisionError):
        evaluate('1 / 0')

def test_example_malformed_expression_empty():
    with pytest.raises(ValueError):
        evaluate('')

def test_example_malformed_expression_unbalanced_parentheses():
    with pytest.raises(ValueError):
        evaluate('(1 + 2')

def test_example_malformed_expression_dangling_operator():
    with pytest.raises(ValueError):
        evaluate('1 + * 2')

def test_example_malformed_expression_two_numbers_in_a_row():
    with pytest.raises(ValueError):
        evaluate('1 2 + 3')

def test_example_malformed_expression_invalid_character():
    with pytest.raises(ValueError):
        evaluate('1 + a')


def test_property_commutativity():
    @given(st.floats(min_value=0), st.floats(min_value=0))
    def check_commutativity(a, b):
        assert evaluate(f'{a} + {b}') == evaluate(f'{b} + {a}'), f"got {evaluate(f'{a} + {b}')!r} and {evaluate(f'{b} + {a}')!r}"


def test_property_associativity():
    @given(st.floats(min_value=0), st.floats(min_value=0), st.floats(min_value=0))
    def check_associativity(a, b, c):
        assert evaluate(f'({a} + {b}) + {c}') == evaluate(f'{a} + ({b} + {c})'), f"got {evaluate(f'({a} + {b}) + {c}')!r} and {evaluate(f'{a} + ({b} + {c})')!r}"


def test_property_idempotence():
    @given(st.floats(min_value=0))
    def check_idempotence(a):
        assert evaluate(f'{a}') == a, f"got {evaluate(f'{a}')!r}"


