    _flatten_helper(obj, flat_dict)
    return flat_dict

def _flatten_helper(obj: Union[Dict[str, Any], List[Any]], flat_dict: Dict[str, Any], parent_key: str = '') -> None:
    if isinstance(obj, dict):
        if not obj:  # Handle empty dict
            flat_dict[parent_key] = {}
        for key, value in obj.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            _flatten_helper(value, flat_dict, new_key)
    elif isinstance(obj, list):
        if not obj:  # Handle empty list
            flat_dict[parent_key] = []
        for index, value in enumerate(obj):
            new_key = f"{parent_key}.{index}" if parent_key else str(index)
            _flatten_helper(value, flat_dict, new_key)
    else:
        flat_dict[parent_key] = obj

    # Remove the empty dict entry if the parent_key is empty and the flat_dict is not empty
    if parent_key == '' and not flat_dict:
        flat_dict.clear()
    elif parent_key == '' and obj == {}:
        flat_dict.clear()  # Clear the flat_dict to avoid adding empty dict entry

def flatten(obj: dict) -> dict:
    result = {}
    _flatten_helper(obj, '', result)
    return result

def _flatten_helper(obj, current_path, result):
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_path = f"{current_path}{key}" + ('.' if current_path else '')
            _flatten_helper(value, new_path, result)
    elif isinstance(obj, list):
        for index, value in enumerate(obj):
            new_path = f"{current_path}{index}." if current_path else f"{index}."
            _flatten_helper(value, new_path, result)
    else:
        result[current_path[:-1]] = obj  # Remove the trailing dot

